{"code":"from pathlib import Path
from capstone import Cs, CS_ARCH_X86, CS_MODE_64

data = bytes(int(x) for x in Path('/workspace/program.txt').read_text().strip().split(','))

md = Cs(CS_ARCH_X86, CS_MODE_64)

# Extract only the instructions that show imul operations
imul_insns = []
for insn in md.disasm(data, 0):
    if insn.mnemonic == 'imul':
        imul_insns.append((insn.address, insn.op_str))

for addr, ops in imul_insns:
    print(f"0x{addr:x}: imul {ops}")

# Also print immediate values from mov qword ptr [rbp - offset], imm
mov_imm = []
for insn in md.disasm(data, 0):
    if insn.mnemonic == 'mov' and 'qword ptr' in insn.op_str and 'rbp' in insn.op_str:
        # Example: mov qword ptr [rbp - 8], 0x4f
        parts = insn.op_str.split(',')
        if len(parts) == 2:
            dest, src = parts
            src = src.strip()
            if src.startswith('0x') or src.isdigit():
                try:
                    v = int(src, 0)
                    mov_imm.append((insn.address, dest.strip(), v))
                except:
                    pass

mov_imm.sort(key=lambda x: x[0])
print("Immediate values loaded into memory:")
for addr, dest, val in mov_imm:
    print(f"0x{addr:x}: {dest} = {val}")"}
